WITH base AS (SELECT *, ROUND(rating * 1.15, 2) AS rating_scaled, CONCAT_WS('/', country, supplier_name) AS country_supplier_name_key, COALESCE(city, 'OTHER') AS city_clean FROM suppliers WHERE city IS NOT NULL AND supplier_name LIKE '%Imports%') SELECT * FROM (SELECT city, country, rating_scaled FROM base) src PIVOT (MAX(rating_scaled) AS total, COUNT(1) AS item_count FOR country IN ('US', 'TH', 'JP'))
